@import "tailwindcss";
@plugin "tailwindcss-animate";

@custom-variant dark (&:is(.dark *));

@layer base {
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  html {
    font-size: 16px;
  }

  body {
    font-size: 1rem;
  }

  *,
  input,
  textarea,
  button {
    line-height: 100%;
    font-family: var(--font-sans);
    font-optical-sizing: auto;
  }

  .text-xs {
    font-size: 0.875rem !important;
    line-height: 1.25rem !important;
  }

  .text-sm {
    font-size: 1rem !important;
    line-height: 1.5rem !important;
  }

  @theme inline {
    --font-heading: var(--font-sans);
    --font-sans:
      "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont,
      "Helvetica Neue", Arial, sans-serif;
    --color-sidebar-ring: var(--sidebar-ring);
    --color-sidebar-border: var(--sidebar-border);
    --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
    --color-sidebar-accent: var(--sidebar-accent);
    --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
    --color-sidebar-primary: var(--sidebar-primary);
    --color-sidebar-foreground: var(--sidebar-foreground);
    --color-sidebar: var(--sidebar);
    --color-chart-5: var(--chart-5);
    --color-chart-4: var(--chart-4);
    --color-chart-3: var(--chart-3);
    --color-chart-2: var(--chart-2);
    --color-chart-1: var(--chart-1);
    --color-ring: var(--ring);
    --color-input: var(--input);
    --color-border: var(--border);
    --color-destructive: var(--destructive);
    --color-destructive-foreground: var(--destructive-foreground);
    --color-accent-foreground: var(--accent-foreground);
    --color-accent: var(--accent);
    --color-muted-foreground: var(--muted-foreground);
    --color-muted: var(--muted);
    --color-secondary-foreground: var(--secondary-foreground);
    --color-secondary: var(--secondary);
    --color-primary-foreground: var(--primary-foreground);
    --color-primary: var(--primary);
    --color-popover-foreground: var(--popover-foreground);
    --color-popover: var(--popover);
    --color-card-foreground: var(--card-foreground);
    --color-card: var(--card);
    --color-foreground: var(--foreground);
    --color-background: var(--background);
    --radius-sm: calc(var(--radius) * 0.6);
    --radius-md: calc(var(--radius) * 0.8);
    --radius-lg: var(--radius);
    --radius-xl: calc(var(--radius) * 1.4);
    --radius-2xl: calc(var(--radius) * 1.8);
    --radius-3xl: calc(var(--radius) * 2.2);
    --radius-4xl: calc(var(--radius) * 2.6);
  }

  :root {
    /* shadcn standard */
    --background: oklch(0.968 0.007 247.896); /* slate-100 #f1f5f9 */
    --foreground: oklch(0.208 0.042 265.755); /* slate-900 #0f172a */
    --card: oklch(1 0 0); /* white */
    --card-foreground: oklch(0.208 0.042 265.755);
    --popover: oklch(1 0 0);
    --popover-foreground: oklch(0.208 0.042 265.755);
    --primary: oklch(0.52 0.228 263); /* #116ddc blue */
    --primary-foreground: oklch(1 0 0);
    --secondary: oklch(0.968 0.007 247.896); /* slate-100 #f1f5f9 */
    --secondary-foreground: oklch(0.208 0.042 265.755);
    --muted: oklch(0.984 0.003 247.858); /* slate-50 #f8fafc */
    --muted-foreground: oklch(0.554 0.046 257.417); /* slate-500 #64748b */
    --accent: oklch(0.97 0.014 254.604); /* blue-50  #eff6ff */
    --accent-foreground: oklch(0.52 0.228 263); /* #116ddc */
    --destructive: oklch(0.637 0.237 25.331); /* red-500  #ef4444 */
    --destructive-foreground: oklch(1 0 0);
    --border: oklch(0.929 0.013 255.508); /* slate-200 #e2e8f0 */
    --input: oklch(1 0 0);
    --ring: oklch(0.52 0.228 263); /* #116ddc */
    --chart-1: oklch(0.52 0.228 263); /* blue   #116ddc */
    --chart-2: oklch(0.696 0.17 162.48); /* teal   #14b8a6 */
    --chart-3: oklch(0.702 0.191 47.604); /* orange #f97316 */
    --chart-4: oklch(0.627 0.265 303.901); /* purple #8b5cf6 */
    --chart-5: oklch(0.548 0.186 151.329); /* green  #059669 */
    --sidebar: oklch(1 0 0); /* white */
    --sidebar-foreground: oklch(0.35 0.01 265); /* #46484e */
    --sidebar-primary: oklch(0.52 0.228 263); /* #116ddc blue */
    --sidebar-primary-foreground: oklch(1 0 0);
    --sidebar-accent: oklch(0.984 0.003 247.858); /* slate-50 #f8fafc */
    --sidebar-accent-foreground: oklch(0.5 0.22 268); /* #3a64f2 */
    --sidebar-border: oklch(0.928 0.013 255); /* light gray */
    --sidebar-ring: oklch(0.5 0.22 268); /* #3a64f2 */
    --sidebar-width: 17rem; /* 272px — match do Figma */
    --sidebar-width-mobile: 18rem;
    --sidebar-width-icon: 3rem; /* largura colapsado */
    --font-sans:
      "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont,
      "Helvetica Neue", Arial, sans-serif;
    --font-serif: Merriweather, ui-serif, serif;
    --font-mono: "Roboto Mono", ui-monospace, monospace;
    --radius: 0.5rem;
    --shadow-x: 4px;
    --shadow-y: 4px;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-opacity: 1;
    --shadow-color: #000000;
    --shadow-2xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
    --shadow-xs: 4px 4px 0px 0px hsl(0 0% 0% / 0.5);
    --shadow-sm:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
    --shadow:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 1px 2px -1px hsl(0 0% 0% / 1);
    --shadow-md:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 2px 4px -1px hsl(0 0% 0% / 1);
    --shadow-lg:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 4px 6px -1px hsl(0 0% 0% / 1);
    --shadow-xl:
      4px 4px 0px 0px hsl(0 0% 0% / 1), 4px 8px 10px -1px hsl(0 0% 0% / 1);
    --shadow-2xl: 4px 4px 0px 0px hsl(0 0% 0% / 2.5);
    --tracking-normal: 0.02em;
    --spacing: 0.25rem;

    /* aliases — mantêm compatibilidade com código existente fora dos componentes UI */
    --white: oklch(1 0 0);
    --background-foreground: var(--card);
    --card-foreground-primary: var(--secondary);
    --card-foreground-secondary: var(--muted);
    --card-foreground-third: var(--accent);
    --text-heading: var(--foreground);
    --text-body: var(--foreground);
    --text-muted: var(--muted-foreground);
    --skeleton: var(--muted);
    --skeleton-foreground: var(--secondary);

    /* tooltip */
    --tooltip-text: #f1f5f9;
    --tooltip-background: #0f172a;

    /* spotlight — RGB para uso com rgba() */
    --spotlight-primary: 17, 109, 220;
    --spotlight-secondary: 248, 250, 252;
    --spotlight-success: 16, 185, 129;
    --spotlight-danger: 244, 63, 94;
    --spotlight-info: 14, 165, 233;
    --spotlight-accent: 234, 179, 8;
    --spotlight-warning: 249, 115, 22;
    --spotlight-teal: 20, 184, 166;

    /* toast */
    --toast-success: 16, 185, 129;
    --toast-danger: 225, 29, 72;
    --toast-info: 14, 165, 233;
    --toast-warning: 251, 146, 60;

    /* badge palette */
    --badge-violet-bg: oklch(0.935 0.052 302); /* #ede0ff */
    --badge-violet-text: oklch(0.375 0.183 295); /* #6b21a8 */
    --badge-emerald-bg: oklch(0.942 0.055 155); /* #d4f5e2 */
    --badge-emerald-text: oklch(0.476 0.109 158); /* #1f7a4d */
    --badge-navy-bg: oklch(0.928 0.059 249); /* #dbe8ff */
    --badge-navy-text: oklch(0.385 0.143 265); /* #1e40af */
    --badge-amber-bg: oklch(0.939 0.063 76); /* #fde9c8 */
    --badge-amber-text: oklch(0.556 0.117 52); /* #a8631a */
    --badge-rose-bg: oklch(0.936 0.045 12); /* #ffe1e6 */
    --badge-rose-text: oklch(0.47 0.174 18); /* #a91d3a */
  }
}

.dark {
  /* shadcn standard */
  --background: oklch(0.1921 0.004 286.0181);
  --foreground: oklch(1 0 0);
  --card: oklch(0.2359 0.0038 286.1058);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.2099 0.0039 286.0588);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.5607 0.2181 266.5346);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.249 0.0056 285.9851);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.210 0.003 286);
  --muted-foreground: oklch(0.5606 0.0091 253.8999);
  --accent: oklch(0 0 0);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.69 0.1762 22.0665);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.36 0.006 286);
  --input: oklch(0.1735 0.002 286.1849);
  --ring: oklch(0.5607 0.2181 266.5346);
  --chart-1: oklch(0.5538 0.2501 277.67);
  --chart-2: oklch(0.8484 0.1234 166.1848);
  --chart-3: oklch(0.8103 0.1158 232.1656);
  --chart-4: oklch(0.8575 0.1752 88.4887);
  --chart-5: oklch(0.634 0.2029 25.0867);
  --sidebar: oklch(0.2359 0.0038 286.1058);
  --sidebar-foreground: oklch(0.7771 0.0115 274.85);
  --sidebar-primary: oklch(0.5607 0.2181 266.5346);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.1921 0.004 286.0181);
  --sidebar-accent-foreground: oklch(0.5607 0.2181 266.5346);
  --sidebar-border: oklch(0.2099 0.0039 286.0588);
  --sidebar-ring: oklch(0.5607 0.2181 266.5346);
  --font-sans:
    "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, "Helvetica Neue",
    Arial, sans-serif;
  --font-serif: Merriweather, ui-serif, serif;
  --font-mono: "Roboto Mono", ui-monospace, monospace;
  --radius: 0.5rem;

  /* aliases — mantêm compatibilidade com código existente fora dos componentes UI */
  --white: oklch(1 0 0);
  --background-foreground: var(--card);
  --card-foreground-primary: var(--secondary);
  --card-foreground-secondary: var(--muted);
  --card-foreground-third: var(--accent);
  --input-background: 34, 40, 64;
  --text-heading: var(--foreground);
  --text-body: var(--foreground);
  --text-muted: var(--muted-foreground);
  --skeleton: var(--muted);
  --skeleton-foreground: var(--secondary);

  /* tooltip */
  --tooltip-text: #f1f5f9;
  --tooltip-background: #334155;

  /* spotlight */
  --spotlight-primary: 17, 109, 220;
  --spotlight-secondary: 10, 25, 41;
  --spotlight-success: 16, 185, 129;
  --spotlight-danger: 244, 63, 94;
  --spotlight-info: 14, 165, 233;
  --spotlight-accent: 234, 179, 8;
  --spotlight-warning: 249, 115, 22;
  --spotlight-teal: 20, 184, 166;

  /* toast */
  --toast-success: 16, 185, 129;
  --toast-danger: 225, 29, 72;
  --toast-info: 14, 165, 233;
  --toast-warning: 251, 146, 60;

  /* badge palette */
  --badge-violet-bg: oklch(0.25 0.08 295);
  --badge-violet-text: oklch(0.78 0.12 302);
  --badge-emerald-bg: oklch(0.25 0.06 155);
  --badge-emerald-text: oklch(0.78 0.12 155);
  --badge-navy-bg: oklch(0.22 0.08 265);
  --badge-navy-text: oklch(0.78 0.1 249);
  --badge-amber-bg: oklch(0.28 0.06 52);
  --badge-amber-text: oklch(0.8 0.11 76);
  --badge-rose-bg: oklch(0.26 0.075 18);
  --badge-rose-text: oklch(0.8 0.1 12);
}

@keyframes theme-icon-in {
  from {
    opacity: 0;
    transform: rotate(-90deg) scale(0.5);
  }
  to {
    opacity: 1;
    transform: rotate(0deg) scale(1);
  }
}

@theme {
  --animate-theme-icon-in: theme-icon-in 0.25s ease;
}

/* InputGroup: adiciona padding automaticamente quando há addon */
[data-slot="input-group"]:has([data-align="inline-start"])
  [data-slot="input-group-input"] {
  padding-left: 2.25rem;
}

[data-slot="input-group"]:has([data-align="inline-end"])
  [data-slot="input-group-input"] {
  padding-right: 2.25rem;
}

/* Ícone de calendário nativo em dark mode */
.dark input[type="date"],
.dark input[type="time"],
.dark input[type="datetime-local"],
.dark input[type="month"],
.dark input[type="week"] {
  color-scheme: dark;
}

/* FormField: estado de erro */
[data-invalid] [data-slot="input-addon"] {
  color: var(--destructive);
}

[data-invalid] [data-slot="input-group-input"] {
  border-color: var(--destructive);
}

[data-invalid] [data-slot="input-group-input"]:focus-visible {
  --tw-ring-color: var(--destructive);
}

@theme inline {
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}
